def main():
    symbols = {}

    def f(typ, expr, rule, source=BEAM_DRILL, **extra):
        return backed(typ, source, expr, rule, **extra)

    n2202_inputs = {
        'frame': f('Dictionary', 'return items.total() < itemCapacity && facingAmount > 0 && enabled;', 'The building frame carrying the live items, facing_amount and enabled keys (BeamDrill.java:270-271, the shouldConsume gate): the gate reads the previous tick facing_amount -- updateConsumption runs before updateTile (BuildingComp.java:2274-2277), so the updateFacing recompute lands after the fold.'),
        'item_capacity': f('int', 'public int itemCapacity = 10;', 'The block itemCapacity from the catalog (block.properties["itemCapacity"]): 10 for plasma-bore, the Block.java:75 field default, and 20 for large-plasma-bore (Blocks.java:3062).', source=BLOCK),
    }
    n2202_outputs = {
        'should_consume': f('bool', 'return items.total() < itemCapacity && facingAmount > 0 && enabled;', 'The shouldConsume gate (BeamDrill.java:270-271): true while the item store is under capacity, at least one facing tile holds mineable wall ore, and the drill is enabled; when false, updateConsumption forces efficiency to zero (BuildingComp.java:1960 + 1992).'),
        'items_total': f('int', 'items.total()', 'The item-store total the gate read (BeamDrill.java:271, items.total() < itemCapacity), computed by the reused drill inventory helper over the frame items Dictionary (the Building.items ItemModule).'),
        'facing_amount': f('int', 'facingAmount > 0', 'The facing wall-ore count the gate read (BeamDrill.java:271, facingAmount > 0): a plain int field (BeamDrill.java:228, Java default 0), recomputed by updateFacing() (BeamDrill.java:375-410) -- the live scan waits for its own slice, so the gate reads the current frame value.'),
    }

    entries = [
        ('N2202', OWNER, 'source_beam_drill_should_consume_state', BEAM_DRILL, 'mindustry.world.blocks.production.BeamDrill.BeamDrillBuild', 'BeamDrillBuild.shouldConsume()', n2202_inputs, n2202_outputs, True, 'Dictionary'),
    ]
    all_names = []
    for sid, owner, prefix, source, cls, method, inputs, outputs, has_contract, return_type in entries:
        names = []
        for suffix, keys in [('input', inputs), ('result', outputs)]:
            name = prefix + '_' + suffix
            for field, meta in keys.items():
                meta['used_by'] = [owner]
                if suffix == 'result':
                    symbol = name + '.' + field
                    names.append(symbol)
                    symbols[symbol] = dict(status='source-backed', godot_owner=owner, godot_symbol=symbol, java_source=meta['java_source'], java_method=method, java_expr=meta['java_expr'], rule=meta['rule'], tests=TESTS, runtime_proof=PROOF)
            source_symbols.upsert_source_state_schema(GODOT, name, dict(status='active', owner=owner, source_slice=sid, keys=keys, runtime_proof=PROOF, rule='Source-backed BeamDrill shouldConsume gate from BeamDrill.java / BuildingComp.java / Blocks.java / Block.java / ItemModule.java.'))
        if has_contract:
            source_symbols.upsert_source_api_contract(GODOT, owner, dict(status='active', source_slice=sid, java_source=source, source_method=method, params=[dict(name=k, type=v['type'], schema=prefix + '_input.' + k) for k, v in inputs.items()], return_type=return_type, return_keys=list(outputs), tests=TESTS, runtime_proof=PROOF, rule='Source-backed BeamDrill shouldConsume gate from BeamDrill.java / BuildingComp.java / Blocks.java / Block.java / ItemModule.java.'))
        all_names.extend(names)

    by_slice = {}
    # The test pins this order: the gate, then the items total it
    # reads, then the facing amount it reads.
    by_slice['N2202'] = [
        'source_beam_drill_should_consume_state_result.should_consume',
        'source_beam_drill_should_consume_state_result.items_total',
        'source_beam_drill_should_consume_state_result.facing_amount',
    ]
    source_symbols.upsert_source_slice(GODOT, 'N2202', dict(status='done', java_source=BEAM_DRILL, java_class='mindustry.world.blocks.production.BeamDrill.BeamDrillBuild', java_method='BeamDrillBuild.shouldConsume()', godot_owner=OWNER, exact_exprs=EXACT_EXPRS, source_symbols=by_slice['N2202'], tests=TESTS, runtime_proof=PROOF, deferred_exprs=DEFERRED))

    source_symbols.upsert_source_symbols(GODOT, symbols)
    source_symbols.write_source_symbol_audit_report(GODOT)
    manifest = json.loads((GODOT / 'src/generated/source_ssot_modules.json').read_text(encoding='utf-8'))
    modules = manifest['modules']
    new_owners = {definition[1] for definition in entries}
    for name, module in modules.items():
        if module.get('canonical_module') == 'api_contracts':
            selected = source_ssot.build_extension_shard(GODOT, name)[module['root_key']]
            if new_owners.intersection(selected):
                optional = module.setdefault('optional_mirror_fields', [])
                if 'return_type' not in optional:
                    optional.append('return_type')
    source_ssot.write_registered_json(GODOT, 'module_manifest', manifest)
    for canonical in ['slice_ledger', 'api_contracts', 'state_schema', 'registry', 'audit_report', 'module_manifest']:
        for name, module in modules.items():
            if module.get('canonical_module') == canonical:
                source_ssot.write_registered_json(GODOT, name, source_ssot.build_extension_shard(GODOT, name))


if __name__ == '__main__':
    main()
